def transform(g):
    h=[r[:] for r in g]
    # bridge centers of diamond patterns aligned on same row or column
    centers=[]
    for r in range(1,len(g)-1):
      for c in range(1,len(g[0])-1):
       if g[r][c-1]==2 and g[r][c+1]==2 and g[r-1][c]==2 and g[r+1][c]==2:
        centers.append((r,c))
    for i,(r,c) in enumerate(centers):
      for rr,cc in centers[i+1:]:
       if r==rr:
        for x in range(min(c,cc)+1,max(c,cc)): h[r][x]=1
       if c==cc:
        for x in range(min(r,rr)+1,max(r,rr)): h[x][c]=1
    return h
